// The search loop's replay after main moved: this run's engine output is put
// back onto the new main (not re-generated by re-running the 40-minute engine,
// which never landed: runs 41313341863 NO_TARGETS, 41316761737 cancelled).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const REPLAY = path.join(here, '..', '.github', 'scripts', 'search_loop_replay.sh');

function run(cwd, cmd, args, env = {}) {
  const r = spawnSync(cmd, args, { cwd, encoding: 'utf8', env: { ...process.env, ...env } });
  return { ok: r.status === 0, out: (r.stdout || '') + (r.stderr || '') };
}
function git(cwd, ...a) { const r = run(cwd, 'git', a); assert.ok(r.ok, `git ${a.join(' ')}: ${r.out}`); return r.out.trim(); }
function w(root, rel, s) { fs.mkdirSync(path.dirname(path.join(root, rel)), { recursive: true }); fs.writeFileSync(path.join(root, rel), s); }
const read = (root, rel) => fs.readFileSync(path.join(root, rel), 'utf8');

function setup() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'sl-replay-'));
  const remote = path.join(dir, 'remote.git');
  git(dir, 'init', '-q', '--bare', '-b', 'main', remote);
  const clone = (name) => {
    const p = path.join(dir, name);
    git(dir, 'clone', '-q', remote, p);
    git(p, 'config', 'user.name', 't'); git(p, 'config', 'user.email', 't@example.com');
    git(p, 'checkout', '-q', '-B', 'main');
    return p;
  };
  const seed = clone('seed');
  w(seed, 'index.html', '<h1>home</h1>\n');
  w(seed, 'sitemap.xml', '<urlset>home</urlset>\n');
  w(seed, '.github/scripts/search_loop_replay.sh', fs.readFileSync(REPLAY, 'utf8'));
  git(seed, 'add', '-A'); git(seed, 'commit', '-qm', 'seed'); git(seed, 'push', '-q', 'origin', 'HEAD:main');
  return { dir, runner: clone('runner'), other: clone('other') };
}

// What search_loop_commit.sh does before handing over to the shared helper.
function savePatch(runner, dir) {
  const patch = path.join(dir, 'engine-output.patch');
  git(runner, 'add', '-A', '-N', '--', '.');
  fs.writeFileSync(patch, run(runner, 'git', ['diff', '--binary', '--full-index', 'HEAD', '--', '.']).out);
  git(runner, 'reset', '-q');
  return patch;
}

test('replay puts this run\'s pages and ledger onto a moved main and keeps main\'s derived files', () => {
  const { dir, runner, other } = setup();
  // The engine run: a new page, the ledger, a related link in home, a sitemap from post-build.
  w(runner, 'questions/how-to-plan/index.html', '<h1>How to plan</h1>\n');
  w(runner, 'data/search-loop/targets.json', '{"targets":[{"query":"how to plan"}]}\n');
  w(runner, 'index.html', '<h1>home</h1>\n<a href="/questions/how-to-plan/">How to plan</a>\n');
  w(runner, 'sitemap.xml', '<urlset>run version</urlset>\n');
  const patch = savePatch(runner, dir);
  // Meanwhile another job moved main and rewrote the same derived sitemap.
  w(other, 'about/index.html', '<h1>about</h1>\n');
  w(other, 'sitemap.xml', '<urlset>main version</urlset>\n');
  git(other, 'add', '-A'); git(other, 'commit', '-qm', 'other job'); git(other, 'push', '-q', 'origin', 'HEAD:main');
  // The shared helper's regenerate_after_remote_advance: reset to the new main, clean, replay.
  git(runner, 'fetch', '-q', 'origin', 'main'); git(runner, 'reset', '-q', '--hard', 'origin/main'); git(runner, 'clean', '-qfd');
  assert.ok(!fs.existsSync(path.join(runner, 'data/search-loop')), 'the clean removed the run output, as in CI');
  const r = run(runner, 'bash', ['-lc', 'bash .github/scripts/search_loop_replay.sh'], { SEARCH_LOOP_PATCH: patch });
  assert.ok(r.ok, r.out);
  assert.equal(read(runner, 'questions/how-to-plan/index.html'), '<h1>How to plan</h1>\n');
  assert.match(read(runner, 'data/search-loop/targets.json'), /how to plan/);
  assert.match(read(runner, 'index.html'), /questions\/how-to-plan/);
  assert.equal(read(runner, 'about/index.html'), '<h1>about</h1>\n', 'main\'s new work is kept');
  // A derived file both sides rewrote keeps main's version: there is no post-build to re-derive it.
  assert.equal(read(runner, 'sitemap.xml'), '<urlset>main version</urlset>\n');
});

test('replay without the saved engine output stops, named', () => {
  const { runner } = setup();
  const r = run(runner, 'bash', ['.github/scripts/search_loop_replay.sh'], { SEARCH_LOOP_PATCH: path.join(runner, 'missing.patch') });
  assert.equal(r.ok, false);
  assert.match(r.out, /NAMED STOP \[SEARCH_LOOP_REPLAY_EMPTY\]/);
});
